return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fa_IR','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-08T20:37:32+00:00','po-revision-date'=>'2026-09-08T20:37:32+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'یک موتور کامل کش و بهینه‌سازی برای WordPress: کش تمام صفحه، کش شیء، پاکسازی پایگاه داده و بهینه‌سازی CSS/JS. زمانی که هاست شما لایه‌ی کش اختصاصی خود را ارائه نمی‌دهد، این را نصب کنید — روی هاستینگ Zinn Digital® به جای آن Zinn® Cache را نصب کنید. کش کردن تمام صفحه به یک سرور LiteSpeed یا OpenLiteSpeed به همراه ماژول LSCache نیاز دارد. یک انشعاب GPLv3 از افزونه LiteSpeed Cache.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d ساعت','%d hour'=>'%d ساعت','%d minutes'=>'%d دقیقه','%d minute'=>'%d دقیقه','Purged All!'=>'همه پاک شدند!','Purged the blog!'=>'وبلاگ پاک‌سازی شد!','Purged the URL!'=>'نشانی وب با موفقیت پاک‌سازی شد!','Purged!'=>'پاکسازی شد!','Failed to upgrade.'=>'ارتقا انجام نشد.','Upgraded successfully.'=>'با موفقیت ارتقا یافت.','Dashboard'=>'داشبورد','OptimaX'=>'اپتیماکس','Presets'=>'پیش‌تنظیم‌ها','General'=>'عمومی','Cache'=>'کش','CDN'=>'شبکه تحویل محتوا (CDN)','Image Optimization'=>'بهینه‌سازی تصویر','Page Optimization'=>'بهینه‌سازی صفحه','Database'=>'پایگاه‌داده','Crawler'=>'خزنده','Toolbox'=>'جعبه‌ابزار','Cookie Name'=>'نام کوک